const body = $json.body || $json || {};
const convIds = Array.isArray(body.conv_ids) ? body.conv_ids : (body.conv_id ? [body.conv_id] : [59, 49]);
const contactIds = Array.isArray(body.contact_ids) ? body.contact_ids : (body.contact_id ? [body.contact_id] : []);
const phoneQueries = Array.isArray(body.phones) ? body.phones : [];
const CW_URL = 'http://chatwoot:3000';
const CW_TOKEN = 'MxVixgmtgZaoKVSarHdWyv1W';
const CW_ACCOUNT = 2;
const H = { api_access_token: CW_TOKEN, 'Content-Type': 'application/json' };

async function req(method, path, bodyObj) {
  try {
    const resp = await this.helpers.httpRequest({
      method,
      url: CW_URL + path,
      headers: H,
      body: bodyObj ? JSON.stringify(bodyObj) : undefined,
      ignoreHttpStatusErrors: true,
      returnFullResponse: true,
      timeout: 30000,
    });
    return { ok: resp.statusCode >= 200 && resp.statusCode < 300, statusCode: resp.statusCode, body: resp.body };
  } catch (e) {
    return { ok: false, error: String(e.message || e).slice(0, 500) };
  }
}

function arrFromMessages(resp) {
  const b = resp?.body;
  if (Array.isArray(b)) return b;
  if (Array.isArray(b?.payload)) return b.payload;
  if (Array.isArray(b?.data?.payload)) return b.data.payload;
  return [];
}

function summarizeMessage(m) {
  return {
    id: m.id,
    message_type: m.message_type,
    private: m.private,
    content_type: m.content_type,
    sender_type: m.sender_type,
    status: m.status,
    source_id: m.source_id,
    created_at: m.created_at,
    content: String(m.content || '').slice(0, 180),
  };
}

const conversations = [];
for (const rawId of convIds) {
  const id = Number(rawId);
  const conv = await req.call(this, 'GET', `/api/v1/accounts/${CW_ACCOUNT}/conversations/${id}`);
  const messages = await req.call(this, 'GET', `/api/v1/accounts/${CW_ACCOUNT}/conversations/${id}/messages`);
  const msgArr = arrFromMessages(messages);
  conversations.push({
    id,
    conversation_status: conv.statusCode,
    conversation_error: conv.error || null,
    conversation: conv.body ? {
      id: conv.body.id,
      display_id: conv.body.display_id,
      status: conv.body.status,
      inbox_id: conv.body.inbox_id,
      inbox: conv.body.inbox ? { id: conv.body.inbox.id, name: conv.body.inbox.name, channel_type: conv.body.inbox.channel_type } : null,
      contact_id: conv.body.contact_id || conv.body.meta?.sender?.id,
      can_reply: conv.body.can_reply,
      assignee_id: conv.body.assignee_id,
      team_id: conv.body.team_id,
      labels: conv.body.labels,
      custom_attributes: conv.body.custom_attributes,
      last_activity_at: conv.body.last_activity_at,
      created_at: conv.body.created_at,
      updated_at: conv.body.updated_at,
      meta: conv.body.meta,
    } : null,
    messages_status: messages.statusCode,
    messages_error: messages.error || null,
    messages_count: msgArr.length,
    private_count: msgArr.filter(m => m.private === true).length,
    public_count: msgArr.filter(m => m.private !== true).length,
    latest_messages: msgArr.slice(-8).map(summarizeMessage),
    private_notes: msgArr.filter(m => m.private === true).slice(-30).map(summarizeMessage),
  });
}

const contacts = [];
for (const rawId of contactIds) {
  const id = Number(rawId);
  const contact = await req.call(this, 'GET', `/api/v1/accounts/${CW_ACCOUNT}/contacts/${id}`);
  const convs = await req.call(this, 'GET', `/api/v1/accounts/${CW_ACCOUNT}/contacts/${id}/conversations`);
  const convArr = Array.isArray(convs.body?.payload) ? convs.body.payload : (Array.isArray(convs.body) ? convs.body : []);
  contacts.push({
    id,
    contact_status: contact.statusCode,
    contact_error: contact.error || null,
    contact: contact.body ? { id: contact.body.id, name: contact.body.name, phone_number: contact.body.phone_number, contact_inboxes: contact.body.contact_inboxes } : null,
    conversations_status: convs.statusCode,
    conversations_count: convArr.length,
    conversations: convArr.map(c => ({ id: c.id, display_id: c.display_id, status: c.status, inbox_id: c.inbox_id, last_activity_at: c.last_activity_at, messages_count: c.messages?.length || 0 })).slice(-10),
  });
}

const searches = [];
for (const phone of phoneQueries) {
  const search = await req.call(this, 'GET', `/api/v1/accounts/${CW_ACCOUNT}/contacts/search?q=${encodeURIComponent(String(phone))}&include_contacts=true`);
  const payload = Array.isArray(search.body?.payload) ? search.body.payload : [];
  searches.push({ phone, status: search.statusCode, count: payload.length, results: payload.map(c => ({ id: c.id, name: c.name, phone_number: c.phone_number, contact_inboxes: c.contact_inboxes })).slice(0, 5) });
}

return [{ json: { ok: true, checked_at: new Date().toISOString(), conversations, contacts, searches } }];
